const a=analysis();const z=await a.impedance().target(a.line({"kind": "coupled-stripline", "widthMm": 0.3, "gapMm": 0.3, "copperThicknessMm": 0.035, "topDielectricHeightMm": 0.3, "bottomDielectricHeightMm": 0.3, "lengthMm": 20, "topMaterial": {"relativePermittivity": 4, "lossTangent": 0, "state": "Explicit homogeneous analytic TEM benchmark"}, "bottomMaterial": {"relativePermittivity": 4, "lossTangent": 0, "state": "Explicit homogeneous analytic TEM benchmark"}})).method('cross-section').frequency({startHz:1e6,stopHz:1e8,points:3,scale:'log'}).budget({maxSeconds:30,maxMemoryMiB:512}).run();a.plot({title:'Genuine coupled FEM',data:z.rlgc});